mapper.select:
SELECT id, batch_id, location_id, in_qty, out_qty
FROM ph_inv_flow
WHERE tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId} AND deleted = b'0'
  AND flow_type = 20 AND biz_type = 2 AND biz_no = #{bizNo} AND biz_line_id = #{bizLineId}
  AND batch_id = #{batchId} AND location_id = #{locationId}
FOR UPDATE

SELECT COALESCE(SUM(in_qty), 0) FROM ph_inv_flow
WHERE tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId} AND deleted = b'0'
  AND flow_type = 21 AND original_flow_id = #{originalFlowId}

mapper.update:
UPDATE ph_inv_batch SET qty_total = qty_total + #{qty}, qty_avail = qty_avail + #{qty}, qty_sold = qty_sold - #{qty},
    version = version + 1, updater = #{operator}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id} AND tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId} AND deleted = b'0' AND qty_sold >= #{qty}
